CREATE TABLE r11_batch(batch_id TEXT PRIMARY KEY,manifest_sha TEXT NOT NULL,release_sha TEXT NOT NULL,role TEXT NOT NULL,code_sha TEXT NOT NULL,science_approved INTEGER NOT NULL DEFAULT 0 CHECK(science_approved=0),training_approved INTEGER NOT NULL DEFAULT 0 CHECK(training_approved=0));
CREATE TABLE r11_source_attempt(attempt_id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES r11_batch(batch_id),paper_key TEXT NOT NULL,asset_key TEXT NOT NULL,original_sha TEXT NOT NULL,attempt_label TEXT NOT NULL,source_status TEXT NOT NULL CHECK(source_status IN ('COMMITTED','QUARANTINED','SCI_REVIEW_HOLD')),native_table_count INTEGER NOT NULL DEFAULT 0,numeric_candidate_count INTEGER NOT NULL DEFAULT 0,paired_candidate_count INTEGER NOT NULL DEFAULT 0,parser_sha TEXT NOT NULL,source_output_sha TEXT,error_category TEXT,created_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE r11_stage_event(stage_id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES r11_source_attempt(attempt_id),sequence INTEGER NOT NULL,stage TEXT NOT NULL,stage_status TEXT NOT NULL,source_sha TEXT NOT NULL,input_digest TEXT,output_digest TEXT,reason TEXT,UNIQUE(attempt_id,sequence));
CREATE TABLE r11_assay_context(assay_id TEXT PRIMARY KEY REFERENCES assay_instance(assay_id),asset_id TEXT NOT NULL REFERENCES asset_ref(asset_id),original_sha TEXT NOT NULL,metric_cell_locator TEXT NOT NULL,metric_cell_sha TEXT NOT NULL,table_id TEXT NOT NULL,time_literal TEXT,unit_literal TEXT,hold_json TEXT NOT NULL CHECK(json_valid(hold_json)),science_approved INTEGER NOT NULL DEFAULT 0 CHECK(science_approved=0),training_approved INTEGER NOT NULL DEFAULT 0 CHECK(training_approved=0));
CREATE TABLE r11_atom_context(atom_id TEXT PRIMARY KEY REFERENCES numeric_atom(atom_id),asset_id TEXT NOT NULL REFERENCES asset_ref(asset_id),original_sha TEXT NOT NULL,source_cell_locator TEXT NOT NULL,source_cell_sha TEXT NOT NULL,source_literal TEXT NOT NULL,source_row INTEGER NOT NULL,source_col INTEGER NOT NULL,metric_cell_locator TEXT NOT NULL,group_label TEXT NOT NULL,group_cell_locator TEXT,group_role TEXT NOT NULL,author_header_json TEXT NOT NULL CHECK(json_valid(author_header_json)),time_literal TEXT,dose_literal TEXT,source_unit TEXT,hold_json TEXT NOT NULL CHECK(json_valid(hold_json)),science_approved INTEGER NOT NULL DEFAULT 0 CHECK(science_approved=0),training_approved INTEGER NOT NULL DEFAULT 0 CHECK(training_approved=0));
CREATE TABLE r11_contrast_context(contrast_id TEXT PRIMARY KEY REFERENCES contrast_proposal(contrast_id),asset_id TEXT NOT NULL REFERENCES asset_ref(asset_id),original_sha TEXT NOT NULL,group_control TEXT NOT NULL,group_treatment TEXT NOT NULL,dose_literal TEXT,time_literal TEXT,unit_literal TEXT,hold_json TEXT NOT NULL CHECK(json_valid(hold_json)),science_approved INTEGER NOT NULL DEFAULT 0 CHECK(science_approved=0),training_approved INTEGER NOT NULL DEFAULT 0 CHECK(training_approved=0));
CREATE TABLE r11_science_hold_detail(hold_id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES asset_ref(asset_id),assay_id TEXT REFERENCES assay_instance(assay_id),reason TEXT NOT NULL,metric_locator TEXT,source_sha TEXT NOT NULL,source_status TEXT NOT NULL CHECK(source_status='SOURCE_HOLD'),source_detail_json TEXT NOT NULL CHECK(json_valid(source_detail_json)));
